// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// The rules of a player's bag: how many of each kind they keep, how many kinds fit and how many of one kind stack.
// The Multiplayer Server decides; the clients draw what it published. SDK-free, so the server and the tests run
// the same code.
import { zoneKey } from './zoneRegistry'

/** One kind in the bag, in the order it first went in; `kind` keeps the spelling it arrived with. */
export interface BagEntry { kind: string; count: number }

export type Bag = BagEntry[]

export interface BagLimits {
  /** kinds that fit at once; 0 is no limit */
  slots: number
  /** most of one kind; 0 is no limit */
  stack: number
  /** kind keys the bag takes; empty takes anything */
  accepts: string[]
}

export type InventoryEventType = 'add' | 'remove' | 'store' | 'take'

export interface InventoryEvent { type: InventoryEventType; player: string; kind: string; count: number }

export const INVENTORY_EVENT_TYPES: InventoryEventType[] = ['add', 'remove', 'store', 'take']

// a record a hand edit or an old version grew past this is cut, so one player can't swell the synced state
const MAX_ENTRIES = 64
const MAX_COUNT = 1_000_000

export const bagKey = zoneKey

export function parseAccepts(text: string): string[] {
  return text.split(/[,;\n]/).map((part) => bagKey(part)).filter(Boolean)
}

export function normalLimits(slots: number, stack: number, accepts: string): BagLimits {
  const whole = (value: number) => (Number.isFinite(value) ? Math.max(0, Math.floor(value)) : 0)
  return { slots: whole(slots), stack: whole(stack), accepts: parseAccepts(accepts) }
}

/** Repairs whatever came off the wire or out of storage: positive whole counts, one entry per kind. */
export function readBag(raw: unknown): Bag {
  if (!Array.isArray(raw)) return []
  const out: Bag = []
  const seen = new Set<string>()
  for (const value of raw) {
    if (out.length >= MAX_ENTRIES) break
    if (typeof value !== 'object' || value === null) continue
    const row = value as Record<string, unknown>
    if (typeof row.kind !== 'string' || typeof row.count !== 'number' || !Number.isFinite(row.count)) continue
    const kind = row.kind.trim()
    const count = Math.min(MAX_COUNT, Math.floor(row.count))
    const key = bagKey(kind)
    if (kind === '' || count <= 0 || seen.has(key)) continue
    seen.add(key)
    out.push({ kind, count })
  }
  return out
}

export function countIn(bag: Bag, kind: string): number {
  const key = bagKey(kind)
  return bag.find((entry) => bagKey(entry.kind) === key)?.count ?? 0
}

export function takesKind(limits: BagLimits, kind: string): boolean {
  const key = bagKey(kind)
  return key !== '' && (limits.accepts.length === 0 || limits.accepts.includes(key))
}

/** How many more of `kind` fit; Infinity when nothing limits it. */
export function roomFor(bag: Bag, kind: string, limits: BagLimits): number {
  if (!takesKind(limits, kind)) return 0
  const have = countIn(bag, kind)
  if (have === 0 && limits.slots > 0 && bag.length >= limits.slots) return 0
  if (limits.stack <= 0) return Infinity
  return Math.max(0, limits.stack - have)
}

/** Adds up to `count`; `added` is what fit (0 leaves the bag as it was). */
export function addToBag(bag: Bag, kind: string, count: number, limits: BagLimits): { bag: Bag; added: number } {
  const want = Math.floor(count)
  const name = kind.trim()
  if (!Number.isFinite(want) || want <= 0 || name === '') return { bag, added: 0 }
  const added = Math.min(want, roomFor(bag, name, limits), MAX_COUNT - countIn(bag, name))
  if (added <= 0) return { bag, added: 0 }
  const key = bagKey(name)
  const at = bag.findIndex((entry) => bagKey(entry.kind) === key)
  if (at < 0) return { bag: [...bag, { kind: name, count: added }], added }
  return { bag: bag.map((entry, i) => (i === at ? { ...entry, count: entry.count + added } : entry)), added }
}

/** Removes exactly `count`, or nothing (null) when the player has fewer. A kind that reaches 0 leaves its slot. */
export function removeFromBag(bag: Bag, kind: string, count: number): Bag | null {
  const want = Math.floor(count)
  if (!Number.isFinite(want) || want <= 0) return null
  const key = bagKey(kind)
  const at = bag.findIndex((entry) => bagKey(entry.kind) === key)
  if (at < 0 || bag[at].count < want) return null
  if (bag[at].count === want) return bag.filter((_, i) => i !== at)
  return bag.map((entry, i) => (i === at ? { ...entry, count: entry.count - want } : entry))
}

/** The synced view: one bag per present player, keyed by lowercase wallet. */
export function readBags(raw: unknown): Record<string, Bag> {
  const out: Record<string, Bag> = {}
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return out
  for (const [player, bag] of Object.entries(raw as Record<string, unknown>)) out[player.toLowerCase()] = readBag(bag)
  return out
}

/** The total of every kind, for the Bag button. */
export function bagTotal(bag: Bag): number {
  return bag.reduce((sum, entry) => sum + entry.count, 0)
}
